DELETE FROM ride_requests
    WHERE request_id IN (
        SELECT
            request_id
        FROM ride_requests AS a
        WHERE a.created_at <= '2024-01-01'::date - INTERVAL '90 days' AND NOT EXISTS (
            SELECT 1 
            FROM driver_responses b 
            WHERE b.request_id = a.request_id
            )
        );

SELECT * FROM ride_requests ORDER BY request_id;
